def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp

    if d_opp == 0:
        if n > 10:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp_at(n - 1)
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    my_streak_d = 0
    i = n - 1
    while i >= 0 and me_at(i) == 'D':
        my_streak_d += 1
        i -= 1

    coop_rate = c_opp / n

    if streak_d >= 3 and my_streak_d >= 5:
        return 'C'

    if n >= 2 and me_at(n - 1) == 'C' and me_at(n - 2) == 'D' and streak_d >= 2:
        return 'C'

    remaining = 100 - n
    if remaining <= 5:
        if coop_rate > 0.6 and streak_d == 0:
            return 'D'
        if coop_rate > 0.75:
            return 'D'
        return 'C'

    if streak_d >= 2:
        return 'D'

    if streak_d == 1:
        if coop_rate > 0.7 and streak_c >= 3:
            return 'C'
        if n >= 4 and opp_at(n - 3) == 'C' and opp_at(n - 4) == 'C':
            return 'C'
        return 'D'

    if coop_rate >= 0.8:
        return 'C'

    if n >= 2:
        mirror_score = 0
        for i in range(1, n):
            if opp_at(i) == me_at(i - 1):
                mirror_score += 1
        if mirror_score >= (n - 1) * 0.7:
            return me_at(n - 1)

    if n >= 6:
        alt_score = 0
        for i in range(1, n):
            if opp_at(i) != opp_at(i - 1):
                alt_score += 1
        if alt_score >= n - 2:
            if last == 'C':
                return 'D'
            return 'C'

    if last == 'C':
        return 'C'
    else:
        if coop_rate > 0.6 and streak_d <= 1:
            return 'C'
        if coop_rate > 0.5 and rng.random() < 0.3:
            return 'C'
        return 'D'
